#include "engine/crowd_navigation.hpp"
#include "engine/dynamic_navigation.hpp"
#include "engine/collider_component.hpp"
#include "engine/scene.hpp"
#include "../src/crowd_demo.hpp"
#include <iostream>
#include <limits>
using namespace engine;
namespace {
void check(bool v,const char* text){if(!v)throw std::runtime_error(text);}
float length(Vec3 v){return std::sqrt(dot(v,v));}
template<class F>void rejects(F fn){try{fn();}catch(const std::exception&){return;}throw std::runtime_error("Expected rejection");}
Actor& box(Scene& scene,Vec3 p,Vec3 half,BodyMotion motion=BodyMotion::Static){auto& a=scene.spawn("Solid");a.transform.position=p;RigidBodySettings s;s.motion=motion;a.addComponent<RigidBodyComponent>("Body",s);a.addComponent<ColliderComponent>("Shape",CollisionShape::box(half));return a;}
struct Group:Actor {CrowdNavigation crowd;Group():Actor("Crowd"){setTickEnabled(true);}void fixedTick(double dt)override{crowd.step(*scene(),dt);}void onDisable()noexcept override{if(scene())crowd.clear(*scene());}void onDespawn()noexcept override{if(scene())crowd.clear(*scene());}};
CharacterMotorComponent& agent(Group& group,Vec3 p){auto& a=group.scene()->spawn<Actor>("Agent");a.transform.position=p;return a.addComponent<CharacterMotorComponent>();}
struct Fixture{Scene scene;Group* group;DynamicNavigation dynamic;Fixture(){box(scene,{0,-.5f,0},{10,.5f,8});group=&scene.spawn<Group>();scene.synchronize();check(dynamic.prepare(scene,0),"Initial navigation bake");}void tick(){dynamic.prepare(scene,1./60);scene.fixedUpdate(1./60);}};
void crossing(){Fixture f;auto& a=agent(*f.group,{-5,0,0});auto& b=agent(*f.group,{5,0,0});f.scene.synchronize();f.group->crowd.add(a,f.dynamic.source(),{5,0,0});f.group->crowd.add(b,f.dynamic.source(),{-5,0,0});float minimum=100;bool deflected=false;for(int i=0;i<900;++i){f.tick();auto s=f.group->crowd.snapshot();minimum=std::min(minimum,std::hypot(s[0].position.x-s[1].position.x,s[0].position.z-s[1].position.z));deflected|=std::abs(s[0].position.z)>.15f;check(f.group->crowd.stats().obstacleQueries<=16,"Avoidance query budget exceeded");}auto s=f.group->crowd.snapshot();std::cout<<"Head-on minimum "<<minimum<<" positions "<<s[0].position.x<<","<<s[0].position.z<<" / "<<s[1].position.x<<","<<s[1].position.z<<" states "<<int(s[0].status)<<","<<int(s[1].status)<<'\n';check(minimum>.59f,"Crowd agents overlapped");check(deflected,"No head-on sidestep");check(s[0].status==NavigationStatus::Arrived&&s[1].status==NavigationStatus::Arrived,"Head-on agents failed to pass and arrive");}
void fourWay(){Fixture f;const Vec3 starts[]={{-5,0,0},{5,0,0},{0,0,-5},{0,0,5}};for(auto p:starts){auto& m=agent(*f.group,p);f.scene.synchronize();f.group->crowd.add(m,f.dynamic.source(),p*-1);}float minimum=100;for(int i=0;i<1500;++i){f.tick();const auto states=f.group->crowd.snapshot();for(std::size_t j=0;j<states.size();++j)for(std::size_t k=j+1;k<states.size();++k)minimum=std::min(minimum,std::hypot(states[j].position.x-states[k].position.x,states[j].position.z-states[k].position.z));}for(const auto& s:f.group->crowd.snapshot()){std::cout<<"Crossing state "<<int(s.status)<<" position "<<s.position.x<<","<<s.position.z<<'\n';check(s.status==NavigationStatus::Arrived,"Four-way agents failed to arrive");}check(minimum>.59f,"Four-way overlap");}
void dynamicObstacle(){Fixture f;auto& door=box(f.scene,{0,1,5},{.65f,1,1.5f},BodyMotion::Kinematic);f.scene.synchronize();const auto body=door.getComponent<RigidBodyComponent>()->id();f.dynamic.track(f.scene,body);f.dynamic.prepare(f.scene,.25);auto& m=agent(*f.group,{-5,0,0});f.scene.synchronize();f.group->crowd.add(m,f.dynamic.source(),{5,0,0});for(int i=0;i<45;++i)f.tick();const auto revision=f.dynamic.source()->revision();auto moved=door.transform;moved.position.z=0;door.getComponent<RigidBodyComponent>()->teleport(moved);f.dynamic.prepare(f.scene,0);check(f.dynamic.source()->revision()>revision,"Moved obstacle did not invalidate navigation");for(int i=0;i<800;++i)f.tick();auto state=f.group->crowd.snapshot()[0];std::cout<<"Dynamic state "<<int(state.status)<<" at "<<state.position.x<<","<<state.position.z<<" preferred "<<state.preferred.x<<","<<state.preferred.z<<" velocity "<<state.velocity.x<<","<<state.velocity.z<<"\n";check(state.status==NavigationStatus::Arrived,"Dynamic obstacle did not produce a usable detour");const auto mesh=std::dynamic_pointer_cast<const NavMesh>(f.dynamic.source()->surface());check(!mesh->project({0,0,0},.1f),"Obstacle footprint remains walkable");const auto builds=f.dynamic.stats().builds;door.destroy();f.scene.synchronize();for(int i=0;i<20;++i)f.tick();check(f.dynamic.stats().builds>builds&&f.dynamic.stats().obstacles==0,"Obstacle removal did not rebuild");check(std::dynamic_pointer_cast<const NavMesh>(f.dynamic.source()->surface())->project({0,0,0},.1f).has_value(),"Removed obstacle did not restore navigation");}
void lifecycle(){Fixture f;auto& m=agent(*f.group,{-4,0,0});f.scene.synchronize();const auto id=m.id();f.group->crowd.add(m,f.dynamic.source(),{4,0,0});rejects([&]{f.group->crowd.add(m,f.dynamic.source(),{});});rejects([&]{f.group->crowd.setGoal(id,{std::numeric_limits<float>::quiet_NaN(),0,0});});f.tick();check(f.group->crowd.snapshot().size()==1,"Invalid request replaced crowd");f.group->crowd.remove(f.scene,id);check(length(m.movementCommand().velocity)==0,"Removal retained motor command");f.group->crowd.add(m,f.dynamic.source(),{4,0,0});m.owner()->enabled=false;f.tick();check(f.group->crowd.snapshot()[0].status==NavigationStatus::Cancelled,"Disabled agent retained navigation");m.owner()->enabled=true;f.tick();check(length(m.movementCommand().velocity)==0,"Re-enabled agent moved without new goal");m.owner()->destroy();f.scene.synchronize();f.tick();auto& replacement=agent(*f.group,{-4,0,0});f.scene.synchronize();check(replacement.id()!=id,"Test did not recycle handle generation");f.tick();check(length(replacement.movementCommand().velocity)==0,"Stale handle commanded replacement motor");Scene other;rejects([&]{f.group->crowd.step(other,.01);});rejects([&]{f.dynamic.prepare(other,.01);});f.group->crowd.clear(f.scene);check(f.group->crowd.snapshot().empty(),"Crowd clear");auto bad=CrowdSettings{};bad.maxAgents=65;rejects([&]{CrowdNavigation c(bad);});}
void failure(){Scene scene;auto& floor=box(scene,{0,-.5f,0},{5,.5f,4});scene.synchronize();DynamicNavigation navigation;check(navigation.prepare(scene,0),"Initial failure-test bake");const auto old=navigation.source()->surface();floor.enabled=false;navigation.invalidate();check(!navigation.prepare(scene,.25)&&!navigation.source()->ready()&&navigation.source()->surface()==old,"Failed bake published stale topology");check(navigation.stats().failures==1,"Bake failure not reported");navigation.prepare(scene,.25);check(navigation.stats().failures==1,"Failed bake retried without request");floor.enabled=true;navigation.invalidate();check(navigation.prepare(scene,.25)&&navigation.source()->ready(),"Restored support failed to publish");auto bad=DynamicNavigationSettings{};bad.rebuildInterval=-1;rejects([&]{DynamicNavigation invalid(bad);});rejects([&]{navigation.prepare(scene,-1);});}
}
void demo(){Scene scene;auto& camera=scene.addChild<CameraComponent>("Camera");OrbitController orbit(camera);CrowdDemo demo;demo.start(scene,orbit);for(int i=0;i<60;++i){demo.prepare(scene,1./60);scene.fixedUpdate(1./60);}demo.door(scene,true);for(int i=0;i<1800;++i){demo.prepare(scene,1./60);scene.fixedUpdate(1./60);}for(const auto& a:demo.agents(scene)){std::cout<<"Demo state "<<int(a.status)<<" at "<<a.position.x<<","<<a.position.z<<'\n';check(a.status==NavigationStatus::Arrived,"Eight-agent demo failed to arrive");}demo.stop(scene,orbit);check(!demo.active(),"Demo failed to restore playground");}
void segment(){Scene scene;box(scene,{0,-.5f,0},{5,.5f,5});scene.synchronize();const std::array obstacles={NavMeshObstacle{{-.7f,0,-1.5f},{.7f,2,1.5f}}};const auto mesh=NavMesh::bakeWithObstacles(scene,obstacles);check(!mesh->canTraverseSegment({-2,0,0},{2,0,0}),"Avoidance segment crossed a carved hole");check(mesh->canTraverseSegment({-2,0,3},{2,0,3}),"Open local segment rejected");rejects([&]{mesh->canTraverseSegment({std::numeric_limits<float>::quiet_NaN(),0,0},{});});const std::array bad={NavMeshObstacle{{1,0,0},{0,1,1}}};rejects([&]{NavMesh::bakeWithObstacles(scene,bad);});}
int main(){try{crossing();fourWay();dynamicObstacle();lifecycle();failure();segment();demo();std::cout<<"Crowd/dynamic navigation tests passed\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
